{
  "application": "ppt-generation",
  "case_id": "case-stackoverflow-survey-work",
  "language": "en",
  "deck": {
    "aspect_ratio": "16:9",
    "slide_count": 8,
    "audience": "engineering managers and HR leaders benchmarking developer compensation and workforce trends",
    "tone": "data-forward, analytical, professional"
  },
  "brief": {
    "title": "Developer Workforce & Compensation Trends — 2024 Stack Overflow Survey",
    "one_liner": "Key findings on employment patterns, salary by role and language, and workplace preferences from 65,000+ developers surveyed in 2024.",
    "goal": "Equip engineering leaders with actionable benchmarks on developer salaries, experience-to-pay ratios, and shifting work-environment preferences to inform hiring and retention strategies."
  },
  "slides": [
    {
      "id": "title-slide",
      "title": "Developer Workforce & Compensation Trends — 2024 Stack Overflow Survey",
      "objective": "Cover slide with deck title, subtitle '65,437 respondents across 180+ countries', and source attribution."
    },
    {
      "id": "employment-status-overview",
      "title": "84% of Developers Are Working, but Full-Time Employment Dips in the U.S.",
      "objective": "Show the global employment status breakdown (full-time 69%, freelance 16.4%, student 13.2%, etc.) and highlight the U.S. drop from 69% to 64.8%. Use a stacked or grouped bar chart comparing global vs. U.S. figures."
    },
    {
      "id": "work-environment-shift",
      "title": "In-Person Work Rises to 20% While Hybrid Holds Steady at 42%",
      "objective": "Visualize the three-year trend of remote vs. hybrid vs. in-person work (2022–2024) using a simple bar or donut chart. Emphasize the steady climb of in-person from 15% to 20%."
    },
    {
      "id": "salary-by-developer-type",
      "title": "Senior Executives and Dev Advocates Top $124K+ Median Salary",
      "objective": "Horizontal bar chart of median salary by developer type (top 10 roles). Include Senior Executive $127K, Dev Advocate $124K, Manager $116K, Dev Experience $109K, SRE $99K, Cloud Infra $97K, etc. Reference figure_1.jpg."
    },
    {
      "id": "salary-vs-experience-scatter",
      "title": "Experience Pays: Top Roles Combine 14+ Years with Six-Figure Salaries",
      "objective": "Scatter plot of median salary (y-axis) vs. average years of experience (x-axis) by developer type, sized or colored by number of responses. Highlight the cluster of senior roles in the upper-right and Student as an outlier at $15K. Reference figure_2.jpg."
    },
    {
      "id": "salary-by-language",
      "title": "Erlang & Clojure Developers Earn >$95K; Dart & Prolog Below $45K",
      "objective": "Scatter plot of median salary vs. average experience by programming language. Call out top earners (Erlang $97K, Clojure $95K, Elixir $93K) and lowest earners (Dart $44K, Prolog $43K, PHP $49K). Note the overall $10K drop in average salary range vs. 2023. Reference figure_3.jpg."
    },
    {
      "id": "company-size-and-purchasing",
      "title": "47% Work at Sub-100 Orgs; 62% Influence Tech Purchases",
      "objective": "Split visual: left side shows company-size distribution (pie or bar), right side shows that 62% of developers influence tech purchases and 60% prefer a build-and-buy approach. Useful context for vendor-side audience."
    },
    {
      "id": "key-takeaways",
      "title": "Takeaways: What These Trends Mean for Hiring & Retention",
      "objective": "Bullet-point summary slide with 4–5 actionable insights: (1) full-time employment softening — plan for more contractors; (2) in-person mandates growing but hybrid still dominant; (3) DevRel and SRE roles command premium pay; (4) language choice correlates with pay — niche languages pay more; (5) most developers influence purchasing — engage them directly."
    }
  ]
}

