42	:root {
43	    /* Titles scale from mobile to desktop */
44	    --title-size: clamp(1.5rem, 5vw, 4rem);
45	    --h2-size: clamp(1.25rem, 3.5vw, 2.5rem);
46	    --h3-size: clamp(1rem, 2.5vw, 1.75rem);
47	
48	    /* Body text */
49	    --body-size: clamp(0.75rem, 1.5vw, 1.125rem);
50	    --small-size: clamp(0.65rem, 1vw, 0.875rem);
51	
52	    /* Spacing scales with viewport */
53	    --slide-padding: clamp(1rem, 4vw, 4rem);
54	    --content-gap: clamp(0.5rem, 2vw, 2rem);
55	    --element-gap: clamp(0.25rem, 1vw, 1rem);
56	}
57	
58	/* 5. Cards/containers use viewport-relative max sizes */
59	.card, .container, .content-box {
60	    max-width: min(90vw, 1000px);
61	    max-height: min(80vh, 700px);
62	}
63	
64	/* 6. Lists auto-scale with viewport */
65	.feature-list, .bullet-list {
66	    gap: clamp(0.4rem, 1vh, 1rem);
67	}
68	
69	.feature-list li, .bullet-list li {
70	    font-size: var(--body-size);
