<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Developer Workforce & Compensation Trends — 2024 Stack Overflow Survey</title>

    <!-- Fonts: Professional clean typography -->
    <link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Manrope:wght@400;500;600;700;800&display=swap">

    <style>
        /* ===========================================
           CSS CUSTOM PROPERTIES (THEME)
           Professional / Data-Forward / Electric Studio
           =========================================== */
        :root {
            /* Colors — Dark professional theme */
            --bg-primary: #0a0a0a;
            --bg-secondary: #111827;
            --bg-card: #1a1a2e;
            --text-primary: #ffffff;
            --text-secondary: #9ca3af;
            --text-muted: #6b7280;
            --accent: #4361ee;
            --accent-secondary: #3b82f6;
            --accent-light: #60a5fa;
            --highlight: #f59e0b;
            --success: #10b981;
            --danger: #ef4444;

            /* Typography — MUST use clamp() */
            --font-display: 'Manrope', sans-serif;
            --font-body: 'Manrope', sans-serif;
            --title-size: clamp(1.75rem, 5vw, 3.5rem);
            --h2-size: clamp(1.25rem, 3vw, 2rem);
            --h3-size: clamp(1rem, 2vw, 1.5rem);
            --body-size: clamp(0.75rem, 1.3vw, 1.1rem);
            --small-size: clamp(0.65rem, 1vw, 0.875rem);
            --label-size: clamp(0.6rem, 0.9vw, 0.75rem);

            /* Spacing — MUST use clamp() */
            --slide-padding: clamp(1.5rem, 4vw, 4rem);
            --content-gap: clamp(0.75rem, 2vw, 1.5rem);
            --element-gap: clamp(0.4rem, 1vw, 0.75rem);

            /* Animation */
            --ease-out-expo: cubic-bezier(0.16, 1, 0.3, 1);
            --duration-normal: 0.6s;
        }

        /* ===========================================
           BASE STYLES
           =========================================== */
        * { margin: 0; padding: 0; box-sizing: border-box; }

        html {
            scroll-snap-type: y mandatory;
            scroll-behavior: smooth;
        }

        body {
            font-family: var(--font-body);
            background: var(--bg-primary);
            color: var(--text-primary);
            line-height: 1.5;
            overflow-x: hidden;
        }

        /* ===========================================
           SLIDE BASE STYLES (from viewport-base.css)
           =========================================== */
        .slide {
            width: 100vw;
            height: 100vh;
            height: 100dvh;
            overflow: hidden;
            scroll-snap-align: start;
            display: flex;
            flex-direction: column;
            position: relative;
        }

        .slide-content {
            flex: 1;
            display: flex;
            flex-direction: column;
            justify-content: center;
            max-height: 100%;
            overflow: hidden;
            padding: var(--slide-padding);
        }

        /* ===========================================
           TYPOGRAPHY
           =========================================== */
        h1 {
            font-size: var(--title-size);
            font-weight: 800;
            line-height: 1.1;
            letter-spacing: -0.02em;
        }

        h2 {
            font-size: var(--h2-size);
            font-weight: 700;
            line-height: 1.2;
            margin-bottom: var(--content-gap);
        }

        h3 {
            font-size: var(--h3-size);
            font-weight: 600;
            line-height: 1.3;
        }

        p {
            font-size: var(--body-size);
            color: var(--text-secondary);
        }

        .subtitle {
            font-size: clamp(0.9rem, 1.8vw, 1.25rem);
            color: var(--text-secondary);
            font-weight: 400;
        }

        .label {
            font-size: var(--label-size);
            text-transform: uppercase;
            letter-spacing: 0.1em;
            color: var(--accent-light);
            font-weight: 600;
        }

        /* ===========================================
           ANIMATIONS
           =========================================== */
        .reveal {
            opacity: 0;
            transform: translateY(20px);
            transition: opacity var(--duration-normal) var(--ease-out-expo),
                        transform var(--duration-normal) var(--ease-out-expo);
        }

        .slide.visible .reveal {
            opacity: 1;
            transform: translateY(0);
        }

        .reveal:nth-child(1) { transition-delay: 0.05s; }
        .reveal:nth-child(2) { transition-delay: 0.1s; }
        .reveal:nth-child(3) { transition-delay: 0.15s; }
        .reveal:nth-child(4) { transition-delay: 0.2s; }
        .reveal:nth-child(5) { transition-delay: 0.25s; }
        .reveal:nth-child(6) { transition-delay: 0.3s; }
        .reveal:nth-child(7) { transition-delay: 0.35s; }
        .reveal:nth-child(8) { transition-delay: 0.4s; }

        /* ===========================================
           NAVIGATION DOTS
           =========================================== */
        .nav-dots {
            position: fixed;
            right: clamp(0.75rem, 2vw, 1.5rem);
            top: 50%;
            transform: translateY(-50%);
            display: flex;
            flex-direction: column;
            gap: 0.5rem;
            z-index: 100;
        }

        .nav-dot {
            width: 8px;
            height: 8px;
            border-radius: 50%;
            background: rgba(255, 255, 255, 0.2);
            cursor: pointer;
            transition: all 0.3s ease;
        }

        .nav-dot.active {
            background: var(--accent);
            transform: scale(1.3);
        }

        .nav-dot:hover {
            background: rgba(255, 255, 255, 0.5);
        }

        /* ===========================================
           PROGRESS BAR
           =========================================== */
        .progress-bar {
            position: fixed;
            top: 0;
            left: 0;
            height: 3px;
            background: var(--accent);
            width: 0%;
            z-index: 1000;
            transition: width 0.3s ease;
        }

        /* ===========================================
           SLIDE 1: TITLE SLIDE
           =========================================== */
        .title-slide {
            background: linear-gradient(135deg, var(--bg-primary) 0%, var(--bg-secondary) 100%);
            justify-content: center;
            align-items: center;
            text-align: center;
        }

        .title-slide::before {
            content: '';
            position: absolute;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            background:
                radial-gradient(ellipse at 30% 20%, rgba(67, 97, 238, 0.15) 0%, transparent 50%),
                radial-gradient(ellipse at 70% 80%, rgba(59, 130, 246, 0.1) 0%, transparent 50%);
            pointer-events: none;
        }

        .title-slide .slide-content {
            position: relative;
            z-index: 1;
            max-width: 900px;
        }

        .title-slide h1 {
            margin-bottom: var(--content-gap);
        }

        .stats-row {
            display: flex;
            justify-content: center;
            gap: clamp(2rem, 5vw, 4rem);
            margin-top: var(--content-gap);
        }

        .stat-item {
            text-align: center;
        }

        .stat-number {
            font-size: clamp(1.5rem, 4vw, 2.5rem);
            font-weight: 800;
            color: var(--accent-light);
        }

        .stat-label {
            font-size: var(--small-size);
            color: var(--text-muted);
            margin-top: 0.25rem;
        }

        .source-badge {
            margin-top: var(--content-gap);
            padding: 0.5rem 1rem;
            background: rgba(67, 97, 238, 0.1);
            border: 1px solid rgba(67, 97, 238, 0.3);
            border-radius: 2rem;
            font-size: var(--small-size);
            color: var(--text-secondary);
            display: inline-block;
        }

        /* ===========================================
           SLIDE 2: EMPLOYMENT STATUS
           =========================================== */
        .employment-slide {
            background: var(--bg-primary);
        }

        .content-grid {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: var(--content-gap);
            max-width: 1200px;
            margin: 0 auto;
            width: 100%;
        }

        @media (max-width: 768px) {
            .content-grid {
                grid-template-columns: 1fr;
            }
        }

        .chart-container {
            background: var(--bg-card);
            border-radius: 1rem;
            padding: var(--content-gap);
            display: flex;
            flex-direction: column;
        }

        .chart-title {
            font-size: var(--small-size);
            font-weight: 600;
            color: var(--text-secondary);
            margin-bottom: var(--element-gap);
        }

        .bar-chart {
            display: flex;
            flex-direction: column;
            gap: 0.75rem;
            flex: 1;
            justify-content: center;
        }

        .bar-row {
            display: flex;
            align-items: center;
            gap: 0.75rem;
        }

        .bar-label {
            width: 100px;
            font-size: var(--small-size);
            color: var(--text-secondary);
            flex-shrink: 0;
        }

        .bar-track {
            flex: 1;
            height: 24px;
            background: rgba(255, 255, 255, 0.1);
            border-radius: 4px;
            overflow: hidden;
            position: relative;
        }

        .bar-fill {
            height: 100%;
            border-radius: 4px;
            transition: width 1s var(--ease-out-expo);
            width: 0;
        }

        .slide.visible .bar-fill {
            width: var(--target-width);
        }

        .bar-fill.global { background: linear-gradient(90deg, var(--accent), var(--accent-secondary)); }
        .bar-fill.us { background: linear-gradient(90deg, var(--highlight), #fbbf24); }

        .bar-value {
            width: 50px;
            font-size: var(--small-size);
            font-weight: 600;
            text-align: right;
            flex-shrink: 0;
        }

        .insight-box {
            background: rgba(245, 158, 11, 0.1);
            border-left: 3px solid var(--highlight);
            padding: var(--element-gap);
            margin-top: var(--element-gap);
            border-radius: 0 0.5rem 0.5rem 0;
        }

        .insight-box p {
            font-size: var(--small-size);
            color: var(--text-primary);
        }

        /* ===========================================
           SLIDE 3: WORK ENVIRONMENT
           =========================================== */
        .environment-slide {
            background: var(--bg-primary);
        }

        .donut-container {
            display: flex;
            flex-direction: column;
            align-items: center;
            gap: var(--content-gap);
        }

        .donut-chart {
            position: relative;
            width: clamp(180px, 30vw, 280px);
            height: clamp(180px, 30vw, 280px);
        }

        .donut-chart svg {
            transform: rotate(-90deg);
        }

        .donut-segment {
            fill: none;
            stroke-width: 40;
            stroke-linecap: round;
            transition: stroke-dasharray 1s var(--ease-out-expo);
        }

        .donut-legend {
            display: flex;
            flex-wrap: wrap;
            gap: var(--element-gap);
            justify-content: center;
        }

        .legend-item {
            display: flex;
            align-items: center;
            gap: 0.5rem;
            font-size: var(--small-size);
        }

        .legend-dot {
            width: 12px;
            height: 12px;
            border-radius: 50%;
        }

        .trend-arrow {
            color: var(--success);
            font-weight: 600;
        }

        .trend-arrow.down {
            color: var(--danger);
        }

        /* ===========================================
           SLIDE 4: SALARY BY DEVELOPER TYPE (BAR CHART)
           =========================================== */
        .salary-slide {
            background: var(--bg-primary);
        }

        .chart-image {
            max-width: 100%;
            max-height: min(55vh, 500px);
            object-fit: contain;
            border-radius: 0.75rem;
            margin: 0 auto;
            display: block;
        }

        .figure-caption {
            text-align: center;
            font-size: var(--small-size);
            color: var(--text-muted);
            margin-top: var(--element-gap);
        }

        /* ===========================================
           SLIDE 5: SALARY VS EXPERIENCE (SCATTER)
           =========================================== */
        .scatter-slide {
            background: var(--bg-primary);
        }

        /* ===========================================
           SLIDE 6: SALARY BY LANGUAGE (SCATTER)
           =========================================== */
        .language-slide {
            background: var(--bg-primary);
        }

        .language-grid {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: var(--content-gap);
            margin-top: var(--element-gap);
        }

        @media (max-width: 768px) {
            .language-grid {
                grid-template-columns: 1fr;
            }
        }

        .language-list {
            display: flex;
            flex-direction: column;
            gap: 0.4rem;
        }

        .language-item {
            display: flex;
            justify-content: space-between;
            align-items: center;
            padding: 0.4rem 0.6rem;
            background: rgba(255, 255, 255, 0.03);
            border-radius: 0.25rem;
            font-size: var(--small-size);
        }

        .language-name {
            font-weight: 500;
        }

        .language-salary {
            font-weight: 700;
            color: var(--accent-light);
        }

        .language-salary.low {
            color: var(--text-muted);
        }

        /* ===========================================
           SLIDE 7: COMPANY SIZE
           =========================================== */
        .company-slide {
            background: var(--bg-primary);
        }

        .split-layout {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: var(--content-gap);
            max-width: 1100px;
            margin: 0 auto;
        }

        @media (max-width: 768px) {
            .split-layout {
                grid-template-columns: 1fr;
            }
        }

        .stat-card {
            background: var(--bg-card);
            border-radius: 1rem;
            padding: var(--content-gap);
            text-align: center;
        }

        .stat-card .big-number {
            font-size: clamp(2rem, 5vw, 3.5rem);
            font-weight: 800;
            color: var(--accent-light);
            line-height: 1;
        }

        .stat-card p {
            margin-top: 0.5rem;
            font-size: var(--small-size);
        }

        .influencer-stats {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: var(--element-gap);
            margin-top: var(--content-gap);
