    <script>
        /* ===========================================
           SLIDE PRESENTATION CONTROLLER
           =========================================== */
        class SlidePresentation {
            constructor() {
                this.slides = document.querySelectorAll('.slide');
                this.currentSlide = 0;
                this.totalSlides = this.slides.length;
                this.progressBar = document.querySelector('.progress-bar');
                this.navDots = document.querySelector('.nav-dots');
                this.scrollTimeout = null;

                this.init();
            }

            init() {
                this.setupIntersectionObserver();
                this.setupKeyboardNav();
                this.setupTouchNav();
                this.setupProgressBar();
                this.setupNavDots();
                this.animateDonutCharts();

                // Mark first slide as visible immediately
                this.slides[0].classList.add('visible');
            }

            setupIntersectionObserver() {
                const options = {
                    root: null,
                    rootMargin: '0px',
                    threshold: 0.5
                };

                const observer = new IntersectionObserver((entries) => {
                    entries.forEach(entry => {
                        if (entry.isIntersecting) {
                            entry.target.classList.add('visible');
                            const slideIndex = parseInt(entry.target.dataset.slide) - 1;
                            this.currentSlide = slideIndex;
                            this.updateProgress();
                            this.updateNavDots();
                        }
                    });
                }, options);

                this.slides.forEach(slide => observer.observe(slide));
            }

            setupKeyboardNav() {
                document.addEventListener('keydown', (e) => {
                    switch(e.key) {
                        case 'ArrowDown':
                        case 'ArrowRight':
                        case ' ':
                        case 'PageDown':
                            e.preventDefault();
                            this.nextSlide();
                            break;
                        case 'ArrowUp':
                        case 'ArrowLeft':
                        case 'PageUp':
                            e.preventDefault();
                            this.prevSlide();
                            break;
                        case 'Home':
                            e.preventDefault();
                            this.goToSlide(0);
                            break;
                        case 'End':
                            e.preventDefault();
                            this.goToSlide(this.totalSlides - 1);
                            break;
                    }
                });
            }

            setupTouchNav() {
                let touchStartY = 0;
                let touchEndY = 0;

                document.addEventListener('touchstart', (e) => {
                    touchStartY = e.changedTouches[0].screenY;
                }, { passive: true });

                document.addEventListener('touchend', (e) => {
                    touchEndY = e.changedTouches[0].screenY;
                    const diff = touchStartY - touchEndY;

                    if (Math.abs(diff) > 50) {
                        if (diff > 0) {
                            this.nextSlide();
                        } else {
                            this.prevSlide();
                        }
                    }
                }, { passive: true });
            }

            setupProgressBar() {
                this.updateProgress();
            }

            updateProgress() {
                const progress = ((this.currentSlide + 1) / this.totalSlides) * 100;
                this.progressBar.style.width = `${progress}%`;
            }

            setupNavDots() {
                // Create dots
                for (let i = 0; i < this.totalSlides; i++) {
                    const dot = document.createElement('div');
                    dot.className = 'nav-dot' + (i === 0 ? ' active' : '');
                    dot.addEventListener('click', () => this.goToSlide(i));
                    this.navDots.appendChild(dot);
                }
            }

            updateNavDots() {
                const dots = this.navDots.querySelectorAll('.nav-dot');
                dots.forEach((dot, index) => {
                    dot.classList.toggle('active', index === this.currentSlide);
                });
            }

            nextSlide() {
                if (this.currentSlide < this.totalSlides - 1) {
                    this.goToSlide(this.currentSlide + 1);
                }
            }

            prevSlide() {
                if (this.currentSlide > 0) {
                    this.goToSlide(this.currentSlide - 1);
                }
            }

            goToSlide(index) {
                this.slides[index].scrollIntoView({ behavior: 'smooth' });
            }

            animateDonutCharts() {
                // Animate donut chart segments on slide 3
                const observer = new IntersectionObserver((entries) => {
                    entries.forEach(entry => {
                        if (entry.isIntersecting) {
                            const segments = entry.target.querySelectorAll('.donut-segment');
                            segments.forEach(segment => {
                                const target = segment.dataset.target;
                                if (target) {
                                    const [dash, total] = target.split(' ').map(Number);
                                    segment.style.strokeDasharray = `${dash} ${total || 440}`;
                                }
                            });
                        }
                    });
                }, { threshold: 0.5 });

                const donutSlide = document.querySelector('.environment-slide');
                if (donutSlide) observer.observe(donutSlide);
            }
        }

        // Initialize
        document.addEventListener('DOMContentLoaded', () => {
            new SlidePresentation();
        });
    </script>
